function handleListSessions(
  ws: WebSocket,
  message: {limit?: number; before?: SessionCursor},
  sessionStore?: SessionStore,
  options?: {history?: {enabled: boolean}}
): void {
  if (!options?.history?.enabled) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'History listing is not enabled');
    return;
  }

  const {userId} = ws as ExtWebSocket;
  if (!userId) {
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Not authenticated');
    return;
  }

  if (!sessionStore?.listFor) {
    sendSessionList(ws, []);
    return;
  }

  const {limit, before} = message;

  sessionStore
    .listFor(userId, {limit, before})
    .then(summaries => {
      const frames: SessionSummaryFrame[] = summaries.map(s => ({
        sessionId: s.sessionId,
        createdAt: s.createdAt.toISOString(),
        updatedAt: s.updatedAt.toISOString(),
        entryCount: s.entryCount,
      }));
      sendSessionList(ws, frames);
    })
    .catch(error => {
      log.error('ws', 'listFor failed', {userId, error: error instanceof Error ? error.message : String(error)});
      sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
    });
}

